param(
    [Parameter(Mandatory=$true)]
    [string]$ruta
)

$lista = Get-ChildItem -Path $ruta -Directory -Recurse | Where-Object {
    (Get-ChildItem $_.FullName -Force).Count -eq 0
}

$lista | ForEach-Object { Write-Host $_.FullName }
Write-Host "Total de carpetas vacías: $($lista.Count)"
